def caesar_cipher(text, shift):
    result = ""
    for char in text:
        if char.isalpha():
            # Convert character to ASCII
            ascii_value = ord(char)
            # Apply the shift with wrap-around
            shifted = (ascii_value - 65 + shift) % 26 + 65 if char.isupper() else (ascii_value - 97 + shift) % 26 + 97
            result += chr(shifted)
        else:
            result += char
    return result

def decrypt_caesar_cipher(text, shift):
