abstract class Vehicle {
    // Abstract property for holding cargo
    abstract var cargo: Any?

    // Abstract method to calculate delivery time
    abstract fun calculateDeliveryTime(distance: Double): Long

    // Method to load cargo
    open fun loadCargo(c: Any) {
        cargo = c
    }

    // Method to unload cargo
    open fun unloadCargo() {
        cargo = null
    }
}

// Car class
class Car : Vehicle() {
    // Extra properties
    var capacity = 4
    var fuelCapacity = 50
    var fuelLevel = 50

    // Overrides
    override var cargo: Any? = null
    override fun calculateDeliveryTime(distance: Double): Long {
        return (distance / 60 * 60 * 1000).toLong()  // Assuming 60 km/h for car
    }

    // Specialized method for refueling
    fun refuel() {
        fuelLevel = fuelCapacity
    }
}

